insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('0b91bfb2-55ed-0be1-0880-6b2a4b23b4b3', 'ru', 'Получить лицензию на розничную реализацию лекарственных средств', 'Работа без лицензии: 15–25 БРВ (ст. 165 КоАО); при крупном доходе — до 55 БРВ или запрет профессии до 5 лет (ст. 190 УК)') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('0b91bfb2-55ed-0be1-0880-6b2a4b23b4b3', 'ru', 'Розничная продажа лекарств — лицензируемый вид деятельности по закону ЗРУ-701. Лицензиар — Агентство по развитию фармацевтической отрасли при Минздраве. Лицензия для фармацевтической деятельности выдаётся на срок от 5 лет. Состав документов и требования к соискателю закреплены в паспорте лицензии (ПКМ №80 от 21.02.2022).', '[{"step":"Подготовить документы по паспорту лицензии (ПКМ №80): регистрационные, о заведующем, о помещении"},{"step":"Подать заявление онлайн через license.gov.uz","cost":"госпошлина ~9 БРВ (≈3,7 млн сум)"},{"step":"Дождаться решения лицензиара","deadline":"15–20 рабочих дней"},{"step":"Проверить запись в открытом реестре лицензий и только затем начинать продажи"}]'::jsonb, '[{"name":"Свидетельство о госрегистрации бизнеса","where_to_get":"birdarcha.uz / ЦГУ"},{"name":"Диплом заведующего о высшем фармацевтическом образовании"},{"name":"Документы на помещение (собственность или аренда)"},{"name":"Сведения о фармацевтическом персонале"}]'::jsonb, '[{"amount":"15–25 БРВ","article":"ст. 165 КоАО","extra":"осуществление лицензируемой деятельности без лицензии"},{"amount":"25/40/55 БРВ или запрет профессии до 5 лет","article":"ст. 190 УК","extra":"при значительном доходе"}]'::jsonb) on conflict do nothing;
