insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('a9fb161f-363a-7ef4-ef84-984daced669e', 'ru', 'Назначить заведующего аптекой с высшим фармацевтическим образованием', 'Отказ в выдаче лицензии или её аннулирование') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('a9fb161f-363a-7ef4-ef84-984daced669e', 'ru', 'Лицензионное требование: аптекой должен руководить специалист с высшим фармацевтическим образованием. Без заведующего заявление на лицензию не пройдёт, а утрата заведующего в работе — основание для приостановления лицензии.', '[{"step":"Принять на работу провизора с высшим фармацевтическим образованием"},{"step":"Оформить приказ о назначении заведующим и приложить диплом к лицензионному досье"}]'::jsonb, '[{"name":"Диплом о высшем фармацевтическом образовании заведующего"}]'::jsonb, '[{"amount":"отказ в лицензии / аннулирование","article":"ПКМ №80","extra":"несоответствие лицензионным требованиям"}]'::jsonb) on conflict do nothing;
