insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('d5d8994f-7ba3-b06d-3ffb-f2e11829140f', 'ru', 'Перед подачей на лицензию соискатель обязан убедиться, что фармацевтический персонал не числится в «чёрном списке» фармработников — это лицензионное требование ПКМ №80.', '[{"step":"Сверить каждого фармспециалиста с реестром недобросовестных работников до подачи заявления"}]'::jsonb, '[]'::jsonb, '[{"amount":"отказ в лицензии","article":"ПКМ №80"}]'::jsonb) on conflict do nothing;
