insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('a5abcabc-97eb-1d69-de1f-6a8d6e364dcf', 'ru', 'Привести помещение аптеки в соответствие с СанПиН', 'Нарушение санитарных норм: 5–10 БРВ, должностные лица 15–20 БРВ (ст. 128 КоАО)') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('a5abcabc-97eb-1d69-de1f-6a8d6e364dcf', 'ru', 'СанПиН №0337-16 задаёт точные параметры аптечного помещения: минимальная площадь 34 м² (с филиалами — от 54 м², сельский аптечный пункт — от 8 м²), размещение на первом этаже с отдельным входом, освещённость торгового зала от 150 люкс, температура не ниже 16°C, пандус для маломобильных посетителей.', '[{"step":"Подобрать помещение с учётом норматива площади (от 34 м²; с филиалами — от 54 м²)"},{"step":"Обеспечить первый этаж, отдельный вход, пандус"},{"step":"Вывести освещённость зала на ≥150 люкс и температуру ≥16°C"}]'::jsonb, '[]'::jsonb, '[{"amount":"5–10 БРВ (должностные лица 15–20)","article":"ст. 128 КоАО","extra":"нарушение санитарных норм и правил"}]'::jsonb) on conflict do nothing;
