insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('caccbbd2-fb99-60fe-b5b1-9c938016bcd1', 'ru', 'Если при аптеке есть склад лекарственных средств, он должен соответствовать СанПиН №0319-15: раздельные температурные зоны, соблюдение холодовой цепи для термолабильных препаратов, контроль температуры и влажности.', '[{"step":"Разметить температурные зоны хранения по группам препаратов"},{"step":"Обеспечить холодовую цепь: холодильное оборудование с журналом контроля температуры"}]'::jsonb, '[]'::jsonb, '[{"amount":"5–10 БРВ (должностные лица 15–20)","article":"ст. 128 КоАО"}]'::jsonb) on conflict do nothing;
