insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('a6941960-ee38-e21e-9d65-caeea6da2b97', 'ru', 'Установить онлайн-кассу с контролем рецептурного отпуска и платёжный терминал', 'Работа без онлайн-кассы: штраф по ст. 164 КоАО') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('a6941960-ee38-e21e-9d65-caeea6da2b97', 'ru', 'Аптека обязана применять онлайн-кассу, передающую чеки в налоговую в реальном времени, и принимать карты через платёжный терминал. Кассовое ПО аптеки должно поддерживать контроль рецептурного отпуска: в зоне пилота э-рецептов касса не пробьёт рецептурный препарат без QR-кода рецепта.', '[{"step":"Купить и зарегистрировать онлайн-ККМ в налоговых органах"},{"step":"Убедиться, что кассовое ПО поддерживает сканирование Data Matrix и QR-кодов э-рецептов"},{"step":"Подключить платёжный терминал для приёма карт"}]'::jsonb, '[]'::jsonb, '[{"amount":"штраф","article":"ст. 164 КоАО","extra":"нарушение порядка применения ККМ"}]'::jsonb) on conflict do nothing;
