insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('d9bc0854-ec95-3bc3-5e53-a313bb744b2a', 'ru', 'Продавать только маркированные лекарства (Asl Belgisi)', 'Прогрессия штрафов: 0,2% → 0,4% → 1% → 2% выручки (ПП-190); возможна приостановка лицензии') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('d9bc0854-ec95-3bc3-5e53-a313bb744b2a', 'ru', 'Цифровая маркировка лекарств обязательна (ПКМ №149 от 02.04.2022). Аптека сканирует Data Matrix-код каждой упаковки при приёмке и при продаже. С 01.08.2025 оборот немаркированных лекарств запрещён полностью — включая старые складские остатки.', '[{"step":"Зарегистрироваться в системе Asl Belgisi и подключить 2D-сканеры"},{"step":"Сканировать каждую упаковку при приёмке товара","deadline":"постоянно"},{"step":"Сканировать код при продаже — выбытие фиксируется чеком","deadline":"постоянно"}]'::jsonb, '[]'::jsonb, '[{"amount":"0,2% → 0,4% → 1% → 2% от выручки","article":"ПП-190","extra":"за повторные нарушения; после 4-го случая — потеря права на возврат НДС на год"},{"amount":"приостановление лицензии","article":"ПКМ №149","extra":"систематический оборот немаркированных лекарств"}]'::jsonb) on conflict do nothing;
