insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('df8fb9b2-23a3-2adc-a227-fccf719cbc91', 'ru', 'На рецептурные препараты действуют предельные наценки: опт ≤15%, розница ≤20%, итоговая цена — не выше зарегистрированной референтной. Безрецептурные препараты с 01.04.2025 продаются по свободным ценам (реформа ПП-411 / УП-13).', '[{"step":"Сверять закупочные и розничные цены рецептурных препаратов с референтными"},{"step":"Держать розничную наценку на рецептурные в пределах 20%","deadline":"постоянно"}]'::jsonb, '[]'::jsonb, '[{"amount":"штраф по итогам проверки","article":"ПП-411","extra":"превышение предельной наценки или референтной цены"}]'::jsonb) on conflict do nothing;
