insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('10b9a159-6fc7-a505-2f08-214dc37721c8', 'ru', 'Препараты с истёкшим сроком годности снимаются с продажи и уничтожаются в установленном порядке. Стоимость уничтожения — невычитаемый расход для налога на прибыль. Реализация просроченных лекарств влечёт санкции вплоть до уголовных.', '[{"step":"Регулярно проверять сроки годности и изымать просрочку из зала","deadline":"постоянно"},{"step":"Передавать просроченные препараты на уничтожение с актом списания"}]'::jsonb, '[]'::jsonb, '[{"amount":"вплоть до уголовной ответственности","article":null,"extra":"реализация просроченных лекарств"}]'::jsonb) on conflict do nothing;
