insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('d0ac01b2-bfcb-b915-f9d7-dde46a5500e9', 'ru', 'Закон ЗРУ-701 делит все виды деятельности на режимы: лицензия (приложение №1, ~75 видов), разрешение (приложение №2, ~140), уведомление (приложение №3, 37). Если вида деятельности нет ни в одном приложении — специальный допуск не нужен, действуют только общие правила.', '[{"step":"Найти свой вид деятельности в приложениях №1–3 к ЗРУ-701"},{"step":"Получить лицензию/разрешение или подать уведомление до начала работы (если требуется)"}]'::jsonb, '[]'::jsonb, '[{"amount":"5–25 БРВ","article":"ст. 165 КоАО","extra":"по нарастанию строгости режима"},{"amount":"25/40/55 БРВ или запрет профессии","article":"ст. 190 УК","extra":"при значительном доходе"}]'::jsonb) on conflict do nothing;
