insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('6f122368-9f2e-54f8-dd80-d99b219379dc', 'ru', 'Компании, оказывающие IT-услуги из перечня IT Park, могут получить резидентство и налоговые льготы. Это право, а не обязанность: проверьте, входит ли ваш вид деятельности в перечень резидентских.', '[{"step":"Сверить вид деятельности с перечнем IT Park и подать заявку на резидентство"}]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict do nothing;
