insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('f497abfd-9de7-dcc9-c448-d193a8111b5b', 'ru', 'Действует мораторий на внеплановые проверки (УП-5490); каждая проверка регистрируется в единой электронной системе. Налоговые: камеральные — по риск-анализу, выездные — не дольше 10 дней, а с 01.01.2026 выездная возможна только после неисполненного предупреждения, выданного за 3 дня.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict do nothing;
