insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('bba85ce4-85ce-d44c-1ce0-a6359174fa8b', 'ru', 'Предприниматель вправе убедиться, что пришедшая проверка зарегистрирована в единой электронной системе проверок, и знать её предмет и основание. Незарегистрированная проверка проводиться не должна.', '[{"step":"При визите проверяющих запросить номер регистрации проверки в единой системе"}]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict do nothing;
